(* A tank fill / settle / drain sequence as a CASE state machine. *)
PROGRAM TankSequence
VAR
    LowFloat AT %IX0.0 : BOOL;    (* TRUE: water at the low mark *)
    HighFloat AT %IX0.1 : BOOL;   (* TRUE: water at the high mark *)
    FillValve AT %QX0.0 : BOOL;
    DrainPump AT %QX0.1 : BOOL;
    FillAlarm AT %QX0.2 : BOOL;
END_VAR
VAR
    Phase : INT := 0;              (* 0 idle, 10 filling, 20 settling, 30 draining, 99 alarm *)
    InPhase : TON;
    LastPhase : INT := -1;
END_VAR

(* the phase timer restarts whenever the phase changes *)
InPhase(IN := (Phase = LastPhase), PT := T#2m);
LastPhase := Phase;

CASE Phase OF
    0:  IF LowFloat THEN Phase := 10; END_IF;
    10: IF HighFloat THEN Phase := 20;
        ELSIF InPhase.Q THEN Phase := 99;      (* filling took over 2 minutes *)
        END_IF;
    20: IF InPhase.ET >= T#10s THEN Phase := 30; END_IF;
    30: IF LowFloat THEN Phase := 0; END_IF;
    99: Phase := 99;                         (* stays here until the PLC is reset *)
END_CASE;

FillValve := (Phase = 10);
DrainPump := (Phase = 30);
FillAlarm := (Phase = 99);
END_PROGRAM
